source.loginUrl:
// 当前书源版本号，切勿修改，否则影响更新的识别
const localVersion = '5.5.2';

let controlUrl = host[0];

function login(flag) {
    if (flag == undefined) {
        result = JSON.parse(source.getLoginInfo())
    } else {
        java.longToast("\n\n💞正在登录中...")
        putLoginInfo(JSON.stringify(result))
    }
    let base_url = getArgument('server') || host[0];
    let zdyserver = String(result['自定义服务器(可不填)']);
    if (zdyserver.includes('http')) {
        setArgument('server', zdyserver);
        if (getKey(String(cookie.getCookie(base_url)))) {
            let cookies = cookie.getCookie(base_url)
            try {
                cookie.removeCookie(base_url)
            } catch (e) {}
            cookie.setCookie(zdyserver, cookies)
        }
        java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
    }
    let plcolor = String(getArgument('plcolor') || result['自定义评论颜色(可不填)'] || '#000000');
    if (plcolor) {
        setArgument('plcolor', plcolor);
    } else {
        setArgument('plcolor', '#000000');
    }
    let zdysources = String(result['自定义搜索源(多个用英文,分割)'] || '');
    if (zdysources) {
        setArgument('sources', zdysources);
    };
    base_url = getArgument('server') || host[0];
    let register_email = String(result['邮箱'])
    let password = String(result['密码'])
    let key = String(result['密钥'] || '')

    if ((register_email && password || key) && !String(getKey(String(cookie.getCookie(base_url))))) {
        try {
            cookie.removeCookie(base_url)
        } catch (e) {}
        let deviceKey = '';
        try {
            deviceKey = java.deviceID();
        } catch (e) {
            deviceKey = java.androidId();
        };
        let deviceId = deviceKey;
        if (register_email && password) {
            let options = JSON.stringify({
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    register_email: result['邮箱'],
                    password: result['密码']
                })
            })
            try {
                let data = JSON.parse(java.ajax(`${base_url}/login_api,${options}`))
                if (data.code == 0) {
                    //java.toast(deviceId)
                    java.toast("\n\n✅️登录成功")
                    cookie.setCookie(base_url, `qttoken=${data.key};deviceId=${deviceId}`)
                    result['密钥'] = data.key
                    setArgument('qttoken', data.key);
                    putLoginInfo(JSON.stringify(result))
                } else {
                    java.toast('\n\n💔' + data.msg || "登录失败，请重试！")
                }
            } catch (e) {
                java.toast("\n\n💔登录失败，请重试！\n" + e.message)
            }
        } else {
            cookie.setCookie(base_url, `qttoken=${key};deviceId=${deviceId}`)
            let res = java.ajax(`${base_url}/user_api,{"method":"POST","headers":{"cookie":"${cookie.getCookie(base_url)}"}}`)
            try {
                res = JSON.parse(res)
                if (res.id != undefined) {
                    setArgument('qttoken', key);
                    java.toast('\n\n密钥登录成功')
                    result['邮箱'] = res.email
                    putLoginInfo(JSON.stringify(result))
                } else {
                    throw new Error()
                }
            } catch (e) {
                java.log(e)
                java.toast("\n\n💔登录失败")
            }
        }
    } else if (flag && String(getKey(String(cookie.getCookie(base_url))))) {
        java.toast("\n\n当前✅️已登录，请🚫退出登录后重新登录");
        //checkStatus();
    } else if (flag) {
        try {
            java.qread();
            java.toast("\n\n请点击右上角✓登陆");
       } catch {
           java.toast("\n\n⛔️请先填写邮箱和密码");
       }

    }
}

function objectToCookieString(obj) {
    if (!obj || typeof obj !== 'object') {
        return '';
    }
    return Object.entries(obj)
        .map(([key, value]) => {
            const stringValue = String(value);
            const encodedKey = encodeURIComponent(key);
            const encodedValue = encodeURIComponent(stringValue);
            return `${encodedKey}=${encodedValue}`;
        })
        .join('; ');
}

function control() {
    controlUrla = getArgument('controlUrl');
    if (controlUrla) {
        controlUrla = findFirstAvailableHost([controlUrla]);
    }
    if (!controlUrla) {
        controlUrla = findFirstAvailableHost(host) || controlUrl;
    }
    setArgument('controlUrl', controlUrla);
    try {
        let open_argument = source.getVariable();
        open_argument = JSON.parse(open_argument);
        let control_cookie = objectToCookieString(open_argument);
        cookie.setCookie(controlUrla, control_cookie);
    } catch {}
    //java.toast(cookie.getCookie(controlUrla))
    java.startBrowserAwait(controlUrla + '/control', '晴天小说设置');
    applyCookieSettings();
}

function applyCookieSettings() {
    let controlUrla = getArgument('controlUrl') || controlUrl;
    var cookieStr = String(cookie.getCookie(controlUrla));

    var cookieData = {};
    if (cookieStr && cookieStr !== 'null' && cookieStr !== 'undefined' && cookieStr !== '') {
        var pairs = cookieStr.split('; ');
        for (var i = 0; i < pairs.length; i++) {
            var pair = pairs[i];
            var eqIndex = pair.indexOf('=');
            if (eqIndex > -1) {
                var key = pair.substring(0, eqIndex).trim();
                var value = decodeURIComponent(pair.substring(eqIndex + 1).trim());
                cookieData[key] = value;
                setArgument(key, value);
            }
        }
    }

    var displayConfig = [{
            key: 'server',
            label: '服务器',
            defaultValue: host[0]
        },
        {
            key: 'proxy',
            label: '访问模式',
            defaultValue: '云端'
        },
        {
            key: 'tab',
            label: '阅读模式',
            defaultValue: '小说'
        },
        {
            key: 'source_type',
            label: '阅读频道',
            defaultValue: '男频'
        },
        {
            key: 'sources',
            label: '书源选择',
            defaultValue: '全部'
        },
        {
            key: 'fqpara',
            label: '段评显示',
            defaultValue: 'on'
        },
        {
            key: 'disabled_sources',
            label: '强制搜索',
            defaultValue: '0'
        },
        {
            key: 'reading',
            label: '同步书架',
            defaultValue: '0'
        },
        {
            key: 'info',
            label: '完整简介',
            defaultValue: 'on'
        }
    ];

    var valueMap = {
        // 访问模式
        '本地': '💻 本地',
        '云端': '☁️ 云端',

        // 开关状态
        'on': '✅ 开启',
        'off': '❌ 关闭',
        '1': '✅ 开启',
        '0': '❌ 关闭',

        // 频道类型
        '男频': '👨 男频',
        '女频': '👩 女频',

        // 内容类型
        '小说': '📖 小说',
        '听书': '🎧 听书',
        '漫画': '🎨 漫画',
        '短剧': '🎬 短剧',

        // 来源类型
        'vip': '💎 VIP专属',
        'svip': '👑 SVIP专属',
        '推荐': '⭐ 网友推荐',
        '全部': '📚 全部'
    };


    var displayLines = [];

    for (var i = 0; i < displayConfig.length; i++) {
        var config = displayConfig[i];
        var value = cookieData[config.key] || config.defaultValue;

        if (!cookieData[config.key]) {
            setArgument(config.key, config.defaultValue);
        }

        var displayValue = valueMap[value] || value;
        if (config.key === 'sources' && displayValue.length > 25) {
            displayValue = displayValue.substring(0, 25) + '...';
        }

        displayLines.push(config.label + ': ' + displayValue);
    }

    // 构建提示模板
    var template = '✨ 当前配置\n';
    template += '━━━━━━━━━━━━━━━━\n';
    template += displayLines.join('\n');
    template += '\n━━━━━━━━━━━━━━━━\n';
    template += '❤️当前应用的 *⚙️书源设置* 中的配置哦❤️'

    // 显示提示
    java.longToast(template);

    return displayLines.length;
}


function reCookieSettings() {
    let controlUrla = getArgument('controlUrl') || controlUrl;
    cookie.removeCookie(controlUrla);
    applyCookieSettings();

}
// 检测服务器
function checkNet() {
    let url = getArgument('server') || host[0];;
    java.longToast(`\n\n♻️正在检测：${url}\n请稍等~`);
    let date1 = new Date().getTime();
    let html = java.ajax(url + '/health');
    let date2 = new Date().getTime();
    let t = date2 - date1;
    let res = {};
    try {
        res = JSON.parse(html);
    } catch {}
    let c = res.status != "healthy";
    let code = 1;
    let time = t / 1000 + 's';
    let logTime = '【' + url + '】\n┋┋\n' + '解析时间：' + time;
    if (c || t > 5000) {
        java.longToast('\n💔【访问失败提示】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️当前接口无法访问(可能被墙)♣️\n┋┋\n请切换其他接口/切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t < 1000) {
        java.longToast('\n💖【网络环境优良】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n❤️延迟低，推荐使用此接口❤️\n┋┋\n网络环境优良，请继续保持状态\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t >= 1000 && t < 2000) {
        java.longToast('\n💛【网络环境一般】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♦️延迟一般，勉强可使用♦️\n┋┋\n请切换其他接口或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    } else if (t >= 2000 && t < 5000) {
        java.longToast('\n💔【网络环境堪忧】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♠延迟过高，不建议使用♠\n┋┋\n请切换其他接口或切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
    }
}


function findFirstAvailableHost(hosts) {
    // 按顺序检测，找到第一个可用的就返回
    for (var i = 0; i < hosts.length; i++) {
        var host = hosts[i];

        try {
            java.longToast("🔍 正在检测: " + host);

            var start = new Date().getTime();
            var response = java.ajax(host + "/health");
            var end = new Date().getTime();
            var time = end - start;

            // 检查是否可用
            if (String(response).indexOf("晴天") !== -1 && time <= 5000) {
                // 显示结果
                var status = "✅ 可用";
                if (time < 1000) {
                    status = "💚 优秀";
                } else if (time < 2000) {
                    status = "💛 一般";
                } else {
                    status = "🧡 较慢";
                }
                java.longToast(status + "\n主机: " + host + "\n延迟: " + time + "ms");
                return host; // 直接返回找到的主机
            }
        } catch (e) {
            // 这个主机失败，继续下一个
        }
    }

    // 所有主机都不可用
    java.longToast("❌ 没有可用的主机");
    return null;
}

function isVips(res) {
    let isVIP = '';
    let vipEndTime = res.vip_end_time;
    let formattedDate = '';

    if (vipEndTime && vipEndTime !== 0) {
        let date = new Date(vipEndTime * 1000);
        formattedDate = `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}-${date.getDate().toString().padStart(2, '0')}`;
        let currentTime = Math.floor(Date.now() / 1000);
        let remainingDays = Math.ceil((vipEndTime - currentTime) / (24 * 60 * 60));
        if (currentTime > vipEndTime) {
            isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"} (已过期)`;
        } else if (remainingDays <= 7) {
            isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"} 剩余${remainingDays}天`;
        } else {
            if (vipEndTime < 1912946812) {
                isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"}(${formattedDate})`;
            } else {
                isVIP = `${res.vip_level === 1 ? "VIP" : "SVIP"} (永久)`;
            }
        }
    } else {
        isVIP = '您尚未开通VIP';
    }
    return isVIP;
}

