function login() {
let time = java.timeFormatUTC(Date.now(),"yyyy-MM-dd'T'HH:mm:ss'+00:00'",8*60*60*1000);
let hash = timemd5(time);
	let headers = {
    'User-Agent': ua,
    'content-type': 'application/x-www-form-urlencoded',
    'x-client-hash': hash,
    'accept-language': a_l,
    'app-version': appv,
    'app-os-version': 'Android 14',
    'x-client-time': time,
    'app-os': 'Android'
  };
  let url = 'https://oauth.secure.pixiv.net/auth/token';
  let Info = source.getLoginInfoMap();
  let tk = Info.token;
  if (!tk) { java.toast('请先填写token'); sleep(600); return; }
  let body = `client_id=MOBrBDS8blbauoSck0ZfDbtuzpyT&client_secret=lsACyCD94FhDUtGTXi3QzcFE2uU1hqtDaKeqrdwj&grant_type=refresh_token&refresh_token=${tk}&include_policy=true`;

  function parseResult(rr) {
  	rr = String(rr);
  	if (/^HTTP\/1\. \d{3}/.test(rr)) { let bi = rr.indexOf('{'); if (bi >= 0) rr = rr.substring(bi); }
  	let m = rr.match(/"access_token"[:\s\"]+([^\"]+)/);
  	if (m) {
  		source.putLoginHeader(m[1]);
  		if (Info.id==''||Info.id==null) {
  			try { Info.id = com.jayway.jsonpath.JsonPath.read(rr, "$.response.user.id"); }
  			catch(e) { try { Info.id = com.jayway.jsonpath.JsonPath.read(rr, "$.user.id"); } catch(e2){} }
  		}
  		source.putLoginInfo(JSON.stringify(Info));
  		java.toast('\n😆登录成功');
  		return true;
  	}
  	if (rr.indexOf('invalid_grant') >= 0) {
  		java.toast('\n⚠️refresh_token已失效\n请重新获取token');
  		sleep(800);
  		return true;
  	}
  	return false;
  }

  //★2026.08免VPN修复：优先走直连通道换token（无VPN可用）
  try {
  	if (parseResult(pxOauth(body))) return;
  } catch(e) {
  	java.log('px oauth直连失败：'+e);
  }

  try {
  	let resp = java.post(url, body, headers);
  	let rr = resp.body();
  	let code = resp.statusCode();
  	java.log('px login post: code='+code+' body='+(rr+'').substring(0,200));
  	if (parseResult(rr)) return;
  	if (code != 200) {
  		java.toast('\n💔登录失败 HTTP '+code+'\n'+(rr+'').substring(0,80));
  		sleep(800);
  		return;
  	}
  } catch(e) {
  	java.log('px login post err: ' + e);
  }

  try {
  	let opt = JSON.stringify({method:'POST', body:body, headers:headers});
  	let rr = (java.connect(url+','+opt).body() + '');
  	java.log('px login connect: '+(rr+'').substring(0,200));
  	if (parseResult(rr)) return;
  } catch(e) {
  	java.log('px login connect err: ' + e);
  }

  java.toast('\n💔登录失败\n请开启VPN后重试');
  sleep(800);
}
